<?php
namespace App\Http\Controllers;use App\Models\User;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;use Illuminate\Validation\Rules\Password;
class AuthController extends Controller{public function showLogin(){return view('auth.login');}public function showRegister(){return view('auth.register');}public function login(Request $r){$data=$r->validate(['email'=>'required|email','password'=>'required|string']);if(auth()->attempt(['email'=>$data['email'],'password'=>$data['password'],'is_active'=>true],$r->boolean('remember'))){$r->session()->regenerate();return redirect()->intended(route('dashboard'));}return back()->withErrors(['email'=>'Invalid credentials or inactive account.'])->onlyInput('email');}public function register(Request $r){$data=$r->validate(['name'=>'required|string|max:100','email'=>'required|email|unique:users,email','phone'=>'nullable|string|max:30','password'=>['required','confirmed',Password::min(8)],'city'=>'nullable|string|max:100']);$user=User::create($data+['role'=>'customer']);auth()->login($user);$r->session()->regenerate();return redirect()->route('dashboard')->with('success','Account created successfully.');}public function logout(Request $r){auth()->logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('login');}}
